arguments:
{"script":"mkdir -p logs
for i in {0..6}; do
  d=$(date -d "-$i day" +%Y-%m-%d)
  f=logs/log_$d.txt
  : >"$f"
  n=$((RANDOM%20+1))
  for j in $(seq 1 $n); do
    case $((RANDOM%4)) in
      0) echo "error at $(date)" >>"$f";;
      1) echo "Error at $(date)" >>"$f";;
      2) echo "no issues $(date)" >>"$f";;
      3) echo "minor error and more Error here $(date)" >>"$f";;
    esac
  done
done
grep -oi 'error' logs/* | wc -l"}
